--- build.ps1 ---
$ws = "<WORKSPACE>"
$site = "$ws\site"
$words = @{}
Get-ChildItem $site -Filter *.html | ForEach-Object {
  $html = Get-Content $_.FullName -Raw -Encoding UTF8
  $key = $_.BaseName
  $links = @()
  foreach ($id in @("sinonimos","analogas")) {
    if ($html -match ('<section id="' + $id + '">.*?</section>')) {
      $sec = $Matches[0]
      [regex]::Matches($sec, '<a href="([^"]+)">') | ForEach-Object {
        $href = $_.Groups[1].Value
        if ($href -ne "index.html") {
          $h = [System.Uri]::UnescapeDataString(($href -replace '\.html$',''))
          $links += @{ to = $h; type = $id }
        }
      }
    }
  }
  if ($html -match '<h1>([^<]+)</h1>') { $name = $Matches[1] } else { $name = $key }
  $words[$key] = @{ name = $name; links = $links }
}
$json = $words | ConvertTo-Json -Depth 6 -Compress
[System.IO.File]::WriteAllText("$ws\words.json", ($words | ConvertTo-Json -Depth 5), [System.Text.UTF8Encoding]::new($false))
$html = Get-Content "$ws\universe\index.html" -Raw -Encoding UTF8
$html = $html.Replace("/*__DATA__*/null", $json)
[System.IO.File]::WriteAllText("$ws\universe\index.html", $html, [System.Text.UTF8Encoding]::new($false))
Write-Output ("words: " + $words.Count + " html size: " + $html.Length)

--- inject.ps1 ---
$ws = "<WORKSPACE>"
$raw = Get-Content "$ws\words.json" -Raw -Encoding UTF8
$w = $raw | ConvertFrom-Json
$out = @{}
foreach ($k in $w.PSObject.Properties.Name) {
  $links = @()
  foreach ($l in $w.$k.links) {
    $type = "analogas"
    # determine type: sinonimos if in sinonimos section; we stored only flat links in words.json
    $links += @{ to = $l; type = "analogas" }
  }
  $out[$k] = @{ name = $w.$k.name; links = $links }
}
$json = $out | ConvertTo-Json -Depth 6 -Compress
$html = Get-Content "$ws\universe\index.html" -Raw -Encoding UTF8
$html = $html.Replace("/*__DATA__*/null", $json)
[System.IO.File]::WriteAllText("$ws\universe\index.html", $html, [System.Text.UTF8Encoding]::new($false))
Write-Output ("injected, html size: " + $html.Length)

--- parse.ps1 ---
$site = "<WORKSPACE>\site"
$words = @{}
Get-ChildItem $site -Filter *.html | ForEach-Object {
  $html = Get-Content $_.FullName -Raw -Encoding UTF8
  $key = $_.BaseName
  $links = @()
  foreach ($id in @("sinonimos","analogas")) {
    if ($html -match ('<section id="' + $id + '">.*?</section>')) {
      $sec = $Matches[0]
      [regex]::Matches($sec, '<a href="([^"]+)">') | ForEach-Object {
        $href = $_.Groups[1].Value
        if ($href -ne "index.html") {
          $h = $href -replace '\.html$',''
          $links += [System.Uri]::UnescapeDataString($h)
        }
      }
    }
  }
  if ($html -match '<h1>([^<]+)</h1>') { $name = $Matches[1] } else { $name = $key }
  $words[$key] = @{ name = $name; links = $links }
}
$json = $words | ConvertTo-Json -Depth 5
[System.IO.File]::WriteAllText("<WORKSPACE>\words.json", $json, [System.Text.UTF8Encoding]::new($false))
Write-Output ("words: " + $words.Count)
$pairCount = 0
foreach ($k in $words.Keys) { foreach ($l in $words[$k].links) { $pairCount++ } }
Write-Output ("link refs: " + $pairCount)

